249	    ys.push(o.y, o.y + o.h / 2, o.y + o.h);
250	  }
251	  return { xs, ys };
252	}
253	
254	function applySmartSnap(mover, excludeIds) {
255	  const { xs, ys } = collectSnapLines(excludeIds);
256	  const my = { xs: [mover.x, mover.x + mover.w / 2, mover.x + mover.w], ys: [mover.y, mover.y + mover.h / 2, mover.y + mover.h] };
257	  guides.length = 0;
258	  let bestX = null, bestY = null;
259	  for (const mx of my.xs) for (const lx of xs) {
260	    const d = Math.abs(mx - lx);
261	    if (d <= SNAP_TOL && (!bestX || d < bestX.d)) bestX = { d, delta: lx - mx, line: lx };
262	  }
263	  for (const myy of my.ys) for (const ly of ys) {
264	    const d = Math.abs(myy - ly);
265	    if (d <= SNAP_TOL && (!bestY || d < bestY.d)) bestY = { d, delta: ly - myy, line: ly };
266	  }
267	  if (bestX) { mover.x += bestX.delta; }
268	  if (bestY) { mover.y += bestY.delta; }
269	  // 参考线：贯穿被吸附物件与参照物之间
270	  if (bestX) {
271	    const targets = snapLineExtent(bestX.line, "x", excludeIds);
272	    guides.push({ axis: "v", at: bestX.line, a: targets.min, b: targets.max });
273	  }
274	  if (bestY) {
275	    const targets = snapLineExtent(bestY.line, "y", excludeIds);
276	    guides.push({ axis: "h", at: bestY.line, a: targets.min, b: targets.max });
277	  }
278	}
279	
280	function snapLineExtent(line, axis, excludeIds) {
281	  let min = line, max = line;
282	  const near = (v) => Math.abs(v - line) < 0.5;
283	  for (const o of items) {
284	    if (excludeIds.has(o.id)) continue;
285	    const vs = axis === "x" ? [o.x, o.x + o.w / 2, o.x + o.w] : [o.y, o.y + o.h / 2, o.y + o.h];
286	    if (vs.some(near)) { min = Math.min(min, axis === "x" ? o.x : o.y); max = Math.max(max, axis === "x" ? o.x + o.w : o.y + o.h); }
287	  }
288	  for (const z of ZONES) {
289	    const vs = axis === "x" ? [z.x, z.x + z.w / 2, z.x + z.w] : [z.y, z.y + z.h / 2, z.y + z.h];
290	    if (vs.some(near)) {
291	      min = Math.min(min, axis === "x" ? z.x : z.y);
292	      max = Math.max(max, axis === "x" ? z.x + z.w : z.y + z.h);
293	    }
294	  }
295	  min = Math.max(min, 0); max = Math.min(max, axis === "x" ? WORLD.w : WORLD.h);
296	  return { min, max };
297	}
298	
299	function scheduleGuideFade() {
300	  renderGuides();
301	  setTimeout(() => { if (guides.length) { guides.length = 0; renderGuides(); } }, 900);
302	}
303	
304	/* ---------- 指针交互（每个动作都有键盘等价物） ---------- */
305	
306	let drag = null; // {mode:'move'|'marquee', ...}
307	
308	function worldPoint(e) {
309	  const r = worldEl.getBoundingClientRect();
310	  return { x: (e.clientX - r.left) / scale, y: (e.clientY - r.top) / scale };
311	}
312	
313	worldEl.addEventListener("pointerdown", (e) => {
314	  if (e.button !== 0) return;
315	  if (renamingId && !e.target.closest(".item-name input")) commitRename(false);
316	  const p = worldPoint(e);
317	  const itemEl = e.target.closest(".item");
318	  if (itemEl) {
319	    const id = itemEl.dataset.id;
320	    if (e.shiftKey) {
321	      selection.has(id) ? selection.delete(id) : selection.add(id);
322	      render();
323	      return;
324	    }
325	    if (!selection.has(id)) { selection.clear(); selection.add(id); render(); }
326	    const primary = byId([...selection][selection.size - 1]) || byId(id);
327	    drag = { mode: "move", start: p, origin: items.filter((it) => selection.has(it.id)).map((it) => ({ id: it.id, x: it.x, y: it.y })), moved: false, ref: primary };
328	    worldEl.setPointerCapture(e.pointerId);
329	  } else {
330	    drag = { mode: "marquee", start: p, base: e.shiftKey ? new Set(selection) : new Set() };
331	    if (!e.shiftKey) { selection.clear(); render(); }
332	    worldEl.setPointerCapture(e.pointerId);
333	  }
334	  e.preventDefault();
335	});
336	
337	worldEl.addEventListener("pointermove", (e) => {
338	  if (!drag) return;
339	  const p = worldPoint(e);
340	  if (drag.mode === "marquee") {
341	    const r = normRect(drag.start, p);
342	    marqueeEl.hidden = false;
343	    marqueeEl.style.cssText = `left:${r.x}px;top:${r.y}px;width:${r.w}px;height:${r.h}px;`;
344	    drag.rect = r;
345	    selection.clear();
346	    drag.base.forEach((id) => selection.add(id));
347	    for (const it of items) {
348	      if (it.x < r.x + r.w && it.x + it.w > r.x && it.y < r.y + r.h && it.y + it.h > r.y) selection.add(it.id);
349	    }
350	    renderItems(); renderStatus();
351	    return;
352	  }
353	  // move
354	  if (!drag.moved) {
355	    if (Math.hypot(p.x - drag.start.x, p.y - drag.start.y) < 3) return;
356	    drag.moved = true;
357	    pushUndo("drag-move");
358	    itemsLayer.classList.add("dragging");
359	  }
360	  const exclude = new Set(selection);
361	  let dx = p.x - drag.start.x, dy = p.y - drag.start.y;
362	  const dxSnap = snapToGrid ? Math.round(dx / GRID) * GRID : dx;
363	  const dySnap = snapToGrid ? Math.round(dy / GRID) * GRID : dy;
364	  const moving = byId(drag.ref.id);
365	  if (moving) {
366	    moving.x = drag.origin.find((o) => o.id === drag.ref.id).x + dxSnap;
367	    moving.y = drag.origin.find((o) => o.id === drag.ref.id).y + dySnap;
368	    applySmartSnap(moving, exclude);
369	    dx = moving.x - drag.origin.find((o) => o.id === drag.ref.id).x;
370	    dy = moving.y - drag.origin.find((o) => o.id === drag.ref.id).y;
371	  }
372	  for (const o of drag.origin) {
373	    const it = byId(o.id);
374	    if (!it || it === moving) continue;
375	    it.x = o.x + dx; it.y = o.y + dy;
376	  }
377	  for (const it of items) if (selection.has(it.id)) clampItem(it);
378	  renderItems(); renderGuides(); renderStatus();
379	});
380	
381	worldEl.addEventListener("pointerup", (e) => {
382	  if (!drag) return;
383	  if (drag.mode === "marquee") { marqueeEl.hidden = true; render(); }
384	  else {
385	    itemsLayer.classList.remove("dragging");
386	    guides.length = 0;
387	    if (drag.moved) render();
388	  }
389	  drag = null;
390	});
391	
392	worldEl.addEventListener("dblclick", (e) => {
393	  const itemEl = e.target.closest(".item");
394	  if (itemEl) { startRename(itemEl.dataset.id); return; }
395	  const p = worldPoint(e);
396	  createAt(snapToGrid ? Math.round((p.x - 60) / GRID) * GRID : p.x - 60,
397	           snapToGrid ? Math.round((p.y - 40) / GRID) * GRID : p.y - 40, 120, 80);
398	});
399	
400	function normRect(a, b) {
401	  return { x: Math.min(a.x, b.x), y: Math.min(a.y, b.y), w: Math.abs(a.x - b.x), h: Math.abs(a.y - b.y) };
402	}
403	
404	/* ---------- 创建 / 复制 / 删除 / 重命名 ---------- */
405	
406	function createAt(x, y, w = 120, h = 80) {
407	  pushUndo("create");
408	  const types = Object.keys(TYPES);
409	  const type = types[createCounter % types.length];
410	  const it = { id: "it-" + Date.now().toString(36) + "-" + createCounter, name: `新物件 ${createCounter}`, type, x, y, w, h };
411	  createCounter++;
412	  clampItem(it);
413	  items.push(it);
414	  selection.clear(); selection.add(it.id);
415	  render();
416	  const z = zoneOf(it);
417	  flash(z ? `已创建「${it.name}」— 已落位于${z.name}（${z.purpose}）` : `已创建「${it.name}」— 方向键移动到目标分区即完成落位`);
418	}
419	
420	function findFreeSpot() {
421	  const w = 120, h = 80;
422	  const cx = WORLD.w / 2 - w / 2, cy = WORLD.h / 2 - h / 2;
423	  for (let ring = 0; ring < 40; ring++) {
424	    const candidates = ring === 0 ? [[cx, cy]] : [];
425	    if (ring > 0) {
426	      const step = GRID * 4;
427	      for (let a = -ring; a <= ring; a += 2) for (let b = -ring; b <= ring; b += 2) {
428	        candidates.push([cx + a * step, cy + b * step]);
429	      }
430	    }
431	    for (const [x, y] of candidates) {
432	      const rect = { x, y, w, h };
433	      if (x < 0 || y < 0 || x + w > WORLD.w || y + h > WORLD.h) continue;
434	      const overlap = items.some((it) => it.x < rect.x + w && it.x + it.w > rect.x && it.y < rect.y + h && it.y + it.h > rect.y);
435	      if (!overlap) return { x: Math.round(x / GRID) * GRID, y: Math.round(y / GRID) * GRID };
436	    }
437	  }
438	  return { x: GRID * 2, y: WORLD.h - h - GRID * 2 };
439	}
440	
441	function duplicateSelection() {
442	  const sel = items.filter((it) => selection.has(it.id));
443	  if (!sel.length) return flash("先选择物件（Tab 或点击）");
444	  pushUndo("duplicate");
445	  const clones = sel.map((it) => ({ ...it, id: "it-" + Date.now().toString(36) + "-" + (createCounter++), x: it.x + 16, y: it.y + 16, name: it.name + " 副本" }));
446	  clones.forEach((c) => { clampItem(c); items.push(c); });
447	  selection.clear();
448	  clones.forEach((c) => selection.add(c.id));
449	  render();
450	  flash(`已复制 ${clones.length} 件`);
451	}
452	
453	function deleteSelection() {
454	  if (!selection.size) return flash("先选择物件（Tab 或点击）");
455	  pushUndo("delete");
456	  const n = selection.size;
457	  items = items.filter((it) => !selection.has(it.id));
458	  selection.clear();
459	  render();
460	  flash(`已删除 ${n} 件 — Ctrl+Z 可撤销`);
461	}
462	
463	function startRename(id) {
464	  renamingId = id;
465	  renderItems();
466	}
467	
468	function commitRename(cancel) {
469	  const input = itemsLayer.querySelector(".item-name input");
470	  const it = byId(renamingId);
471	  renamingId = null;
472	  if (it && input && !cancel) {
473	    const name = input.value.trim();
474	    if (name && name !== it.name) { pushUndo("rename"); it.name = name; }
475	  }
476	  render();
477	}
478	
479	itemsLayer.addEventListener("keydown", (e) => {
480	  if (e.target.tagName !== "INPUT") return;
481	  if (e.key === "Enter") { e.preventDefault(); commitRename(false); }
482	  else if (e.key === "Escape") { e.preventDefault(); commitRename(true); }
483	  e.stopPropagation();
484	});
485	
486	itemsLayer.addEventListener("focusout", (e) => {
487	  if (e.target.tagName === "INPUT" && renamingId) commitRename(false);
488	});
489	
490	/* ---------- 键盘契约（验收种子：空间操作有键盘等价物） ---------- */
491	
492	document.addEventListener("keydown", (e) => {
493	  if (e.target.tagName === "INPUT") return; // 重命名输入时让位
494	  const mod = e.ctrlKey || e.metaKey;
495	  const onButton = e.target.tagName === "BUTTON"; // 焦点在工具条按钮上时保留原生键盘语义
496	
497	  if (mod && (e.key === "z" || e.key === "Z")) { e.preventDefault(); e.shiftKey ? redo() : undo(); return; }
498	  if (mod && (e.key === "y" || e.key === "Y")) { e.preventDefault(); redo(); return; }
499	  if (mod && (e.key === "d" || e.key === "D")) { e.preventDefault(); duplicateSelection(); return; }
500	  if (mod && (e.key === "a" || e.key === "A")) { e.preventDefault(); items.forEach((it) => selection.add(it.id)); render(); return; }
501	
502	  switch (e.key) {
503	    case "Tab": {
504	      if (onButton) return; // 允许 Tab 在工具条按钮间移动焦点
505	      e.preventDefault();
506	      cycleSelection(e.shiftKey ? -1 : 1);
507	      return;
508	    }
509	    case "Escape":
510	      e.preventDefault();
511	      if (helpOpen) { toggleHelp(false); return; }
512	      if (renamingId) { commitRename(true); return; }
513	      selection.clear(); render();
514	      return;
515	    case "?": case "k": case "K":
516	      e.preventDefault();
517	      toggleHelp();
518	      return;
519	    case "n": case "N": {
520	      e.preventDefault();
521	      const spot = findFreeSpot();
522	      createAt(spot.x, spot.y);
523	      return;
524	    }
525	    case "Delete": case "Backspace":
526	      e.preventDefault();
527	      deleteSelection();
528	      return;
529	    case "Enter": {
530	      if (onButton) return; // 按钮自身的激活语义优先
531	      const first = [...selection][selection.size - 1];
532	      if (first) { e.preventDefault(); startRename(first); }
533	      return;
534	    }
535	    case "[" : zorder(-1); return;
536	    case "]" : zorder(1); return;
537	    case "g": case "G":
538	      snapToGrid = !snapToGrid;
539	      render();
540	      flash(`网格吸附已${snapToGrid ? "开启" : "关闭"}`);
541	      return;
542	    case "d": distribute("h"); return;
543	    case "D": distribute("v"); return;
544	  }
545	
546	  if (e.key.startsWith("Arrow")) {
547	    e.preventDefault();
548	    nudge(e);
549	    return;
550	  }
551	
552	  if (/^[1-6]$/.test(e.key)) { alignTo(e.key); return; }
553	});
554	
555	function cycleSelection(dir) {
556	  if (!items.length) return;
557	  const ordered = items; // 数组顺序即 z 序
558	  let idx = -1;
559	  const current = [...selection][selection.size - 1];
560	  if (current) idx = ordered.findIndex((it) => it.id === current);
561	  let next = (idx + dir + ordered.length) % ordered.length;
562	  if (idx === -1 && dir === -1) next = ordered.length - 1;
563	  selection.clear();
564	  selection.add(ordered[next].id);
565	  renamingId = null;
566	  render();
567	}
568	
569	function nudge(e) {
570	  const sel = items.filter((it) => selection.has(it.id));
571	  if (!sel.length) { flash("先按 Tab 选择物件，或 N 新建"); return; }
572	  const step = e.shiftKey ? BIG_STEP : GRID;
573	  const dx = e.key === "ArrowLeft" ? -step : e.key === "ArrowRight" ? step : 0;
574	  const dy = e.key === "ArrowUp" ? -step : e.key === "ArrowDown" ? step : 0;
575	  pushUndo("nudge");
576	  const exclude = new Set(selection);
577	  for (const it of sel) {
578	    it.x += dx; it.y += dy;
579	    if (e.altKey) {
580	      // 键盘等价物：移动并智能对齐吸附（与拖拽吸附同一语义）
581	      applySmartSnap(it, new Set([...exclude].filter((id) => id !== it.id)));
582	    }
583	    clampItem(it);
584	  }
585	  if (e.altKey) scheduleGuideFade(); else { guides.length = 0; }
586	  render();
587	  const primary = sel[sel.length - 1];
588	  const z = zoneOf(primary);
589	  if (z && sel.length === 1) flash(`落位：${z.name} · ${z.purpose}`);
590	}
591	
592	/* 1-6 对齐：单选 → 对齐所在分区（未安置则对齐画布）；多选 → 组内对齐 */
593	function alignTo(key) {
594	  const sel = items.filter((it) => selection.has(it.id));
595	  if (!sel.length) return flash("先选择物件");
596	  let target;
597	  if (sel.length === 1) {
598	    const z = zoneOf(sel[0]);
599	    target = z ? { x: z.x, y: z.y, w: z.w, h: z.h } : { x: 0, y: 0, w: WORLD.w, h: WORLD.h };
600	  } else {
601	    const minX = Math.min(...sel.map((i) => i.x)), minY = Math.min(...sel.map((i) => i.y));
602	    const maxX = Math.max(...sel.map((i) => i.x + i.w)), maxY = Math.max(...sel.map((i) => i.y + i.h));
603	    target = { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
604	  }
605	  pushUndo("align");
606	  for (const it of sel) {
607	    switch (key) {
608	      case "1": it.x = target.x; break;
609	      case "2": it.x = target.x + (target.w - it.w) / 2; break;
610	      case "3": it.x = target.x + target.w - it.w; break;
611	      case "4": it.y = target.y; break;
612	      case "5": it.y = target.y + (target.h - it.h) / 2; break;
613	      case "6": it.y = target.y + target.h - it.h; break;
614	    }
615	    clampItem(it);
616	  }
617	  render();
618	  flash(`已对齐（${ { "1": "左", "2": "水平居中", "3": "右", "4": "顶", "5": "垂直居中", "6": "底" }[key] }）`);
619	}
620	
621	function distribute(axis) {
622	  const sel = items.filter((it) => selection.has(it.id));
623	  if (sel.length < 3) return flash("均分至少需要选中 3 件（Shift+点击 或 Ctrl+A 加选）");
624	  pushUndo("distribute");
625	  const sorted = [...sel].sort((a, b) => (axis === "h" ? a.x - b.x : a.y - b.y));
626	  const first = sorted[0], last = sorted[sorted.length - 1];
627	  if (axis === "h") {
628	    const span = (last.x - first.x) || 1;
629	    const inner = sorted.length - 1;
630	    sorted.forEach((it, i) => { it.x = Math.round(first.x + (span * i) / inner); clampItem(it); });
631	  } else {
632	    const span = (last.y - first.y) || 1;
633	    const inner = sorted.length - 1;
634	    sorted.forEach((it, i) => { it.y = Math.round(first.y + (span * i) / inner); clampItem(it); });
635	  }
636	  render();
637	  flash(`已${axis === "h" ? "水平" : "垂直"}均分 ${sel.length} 件`);
638	}
639	
640	function zorder(dir) {
641	  const sel = items.filter((it) => selection.has(it.id));
642	  if (!sel.length) return flash("先选择物件");
643	  pushUndo("zorder");
644	  if (dir > 0) {
645	    for (let i = items.length - 2; i >= 0; i--) {
646	      if (selection.has(items[i].id) && !selection.has(items[i + 1].id)) {
647	        [items[i], items[i + 1]] = [items[i + 1], items[i]];
648	      }
649	    }
650	  } else {
651	    for (let i = 1; i < items.length; i++) {
652	      if (selection.has(items[i].id) && !selection.has(items[i - 1].id)) {
653	        [items[i], items[i - 1]] = [items[i - 1], items[i]];
654	      }
655	    }
656	  }
657	  render();
658	}
659	
660	/* ---------- 覆盖层与工具条 ---------- */
661	
662	function toggleHelp(force) {
663	  helpOpen = force !== undefined ? force : !helpOpen;
664	  helpEl.hidden = !helpOpen;
665	}
666	
667	$("#btn-new").addEventListener("click", (e) => { const s = findFreeSpot(); createAt(s.x, s.y); e.currentTarget.blur(); });
668	$("#btn-delete").addEventListener("click", (e) => { deleteSelection(); e.currentTarget.blur(); });
669	$("#btn-undo").addEventListener("click", (e) => { undo(); e.currentTarget.blur(); });
670	$("#btn-redo").addEventListener("click", (e) => { redo(); e.currentTarget.blur(); });
671	$("#btn-snap").addEventListener("click", (e) => { snapToGrid = !snapToGrid; render(); e.currentTarget.blur(); });
672	$("#btn-help").addEventListener("click", () => toggleHelp());
673	$("#btn-help-close").addEventListener("click", () => toggleHelp(false));
674	helpEl.addEventListener("click", (e) => { if (e.target === helpEl) toggleHelp(false); });
675	
676	/* ---------- 自适应缩放（画布总是完整可见，无平移导航） ---------- */
677	
678	function fit() {
679	  const wrap = $("#canvas-wrap");
680	  const availW = wrap.clientWidth - 28;
681	  const availH = wrap.clientHeight - 28;
682	  scale = Math.min(1, availW / WORLD.w, availH / WORLD.h);
683	  scalerEl.style.width = WORLD.w * scale + "px";
684	  scalerEl.style.height = WORLD.h * scale + "px";
685	  worldEl.style.transform = `scale(${scale})`;
686	}
687	window.addEventListener("resize", fit);
688	
689	/* ---------- 供验证脚本读取（只读快照） ---------- */
690	
691	window.__setplot = {
692	  get items() { return items.map((it) => ({ ...it, zone: zoneOf(it) ? zoneOf(it).id : null })); },
693	  get selection() { return [...selection]; },
694	  zoneOf: (name) => { const it = items.find((i) => i.name === name); return it ? (zoneOf(it) ? zoneOf(it).name : null) : undefined; },
695	};
696	
697	/* ---------- 启动：同步首渲染，无加载态 ---------- */
698	
699	renderZones();
700	renderItems();
701	fit();
702	render();
703

